(6231858, 921309, 101668, '<td valign="top">Very nice I love the picture but the forground is too prominent for a clouds picture. It does match challenge but I''d love to see clouds feature more 6</td>', 'Very nice I love the picture but the forground is too prominent for a clouds picture. It does match challenge but I''d love to see clouds feature more 6', '2010-11-24 04:52:04.000000', NULL, 1),
(6231860, 920966, 101668, '<td valign="top">Oh great</td>', 'Oh great', '2010-11-24 04:52:28.000000', NULL, 1),
(6231865, 921658, 108069, '<td valign="top">This is so eerily similar to my bike ride to work it''s scary. Only difference is that there are fields on my right and the road is to the left of the line of trees. Same weather for the past two months as well. Cool shot.</td>', 'This is so eerily similar to my bike ride to work it''s scary. Only difference is that there are fields on my right and the road is to the left of the line of trees. Same weather for the past two months as well. Cool shot.', '2010-11-24 05:14:05.000000', NULL, 1),
(6231867, 921602, 108069, '<td valign="top">Nicely spotted scene and the clouds certainly have got potential, but it seems a bit over-sharpened. Or something. The clouds just seem unnatural. Colors are great and the composition is as well. Not voting, just commenting.</td>', 'Nicely spotted scene and the clouds certainly have got potential, but it seems a bit over-sharpened. Or something. The clouds just seem unnatural. Colors are great and the composition is as well. Not voting, just commenting.', '2010-11-24 05:28:33.000000', NULL, 1),
(6231870, 920997, 110041, '<td valign="top">I like the moody feel you''ve captured with the tones.</td>', 'I like the moody feel you''ve captured with the tones.', '2010-11-24 05:43:10.000000', NULL, 1),
(6231875, 920552, 110041, '<td valign="top">If the birds were that little bit higher against the sky! Good effort all the same.</td>', 'If the birds were that little bit higher against the sky! Good effort all the same.', '2010-11-24 05:46:51.000000', NULL, 1),
(6231889, 921567, 108069, '<td valign="top">Truly awesome capture, great tones and excellent color. Composition couldn''t have worked out better with the strikes. I''m not voting but that border is horrible in my opinion. Completely unnecessary with such a wonderful photo. I''ll be shocked (seriously, no pun intended) if you don''t grab a ribbon with this.</td>', 'Truly awesome capture, great tones and excellent color. Composition couldn''t have worked out better with the strikes. I''m not voting but that border is horrible in my opinion. Completely unnecessary with such a wonderful photo. I''ll be shocked (seriously, no pun intended) if you don''t grab a ribbon with this.', '2010-11-24 06:13:59.000000', NULL, 1),
(6231938, 921232, 108069, '<td valign="top">Wonderful photo. Great tones.</td>', 'Wonderful photo. Great tones.', '2010-11-24 07:22:50.000000', NULL, 1),
(6231946, 921419, 110041, '<td valign="top">good exposure for the clouds but the rest of the frame is too dark especially the large dark block in the lower left.</td>', 'good exposure for the clouds but the rest of the frame is too dark especially the large dark block in the lower left.', '2010-11-24 07:34:15.000000', NULL, 1),
