(6232154, 921539, 33736, '<td valign="top">The exposure and focus on the clouds is not well done - blurred and blown.</td>', 'The exposure and focus on the clouds is not well done - blurred and blown.', '2010-11-24 10:37:52.000000', NULL, 1),
(6232157, 920997, 33736, '<td valign="top">The water drops are wonderful.</td>', 'The water drops are wonderful.', '2010-11-24 10:39:15.000000', NULL, 1),
