(6232593, 921442, 15711, '<td valign="top">Love that song.  This is spooky!!</td>', 'Love that song.  This is spooky!!', '2010-11-24 20:10:45.000000', NULL, 1),
(6232595, 921668, 15711, '<td valign="top">They almost don''t look real. Wonderful!</td>', 'They almost don''t look real. Wonderful!', '2010-11-24 20:11:31.000000', NULL, 1),
(6232654, 921239, 40391, '<td valign="top">I wonder what colour your ribbon will be.  Excellent shot! 10</td>', 'I wonder what colour your ribbon will be.  Excellent shot! 10', '2010-11-24 21:28:31.000000', NULL, 1),
(6232688, 921543, 21714, '<td valign="top">Peaceful. I like it.</td>', 'Peaceful. I like it.', '2010-11-24 22:47:02.000000', NULL, 1),
(6232855, 921533, 86218, '<td valign="top">Im not sure about this image and the clarity in it. Is it dust on the sensor in the clouds? whatever it is, it''s really breaking the image down. I do like the three layers and the breaks you have in it. You have the elements for a much better photo than what I think this would eventually score. Nothing wrong with your vision. You have to work on pp and cleaner images and Im sure you would have do even better</td>', 'Im not sure about this image and the clarity in it. Is it dust on the sensor in the clouds? whatever it is, it''s really breaking the image down. I do like the three layers and the breaks you have in it. You have the elements for a much better photo than what I think this would eventually score. Nothing wrong with your vision. You have to work on pp and cleaner images and Im sure you would have do even better', '2010-11-25 05:22:12.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6232858, 921665, 86218, '<td valign="top">Why cant I not get to dislike these shots. 10 Just brilliant. Currently a discussion on the threads about people having better clouds than others. C''mon. This is what Im talking about</td>', 'Why cant I not get to dislike these shots. 10 Just brilliant. Currently a discussion on the threads about people having better clouds than others. C''mon. This is what Im talking about', '2010-11-25 05:26:46.000000', NULL, 1),
(6232859, 921289, 86218, '<td valign="top">Im mad at you. Should have cropped these horrible lights at the bottom. You should have one excluding the flying objects. What are thos ugly reflections up in the sky? Appart from this, this would be one of my top photos</td>', 'Im mad at you. Should have cropped these horrible lights at the bottom. You should have one excluding the flying objects. What are thos ugly reflections up in the sky? Appart from this, this would be one of my top photos', '2010-11-25 05:29:57.000000', NULL, 1),
(6232862, 920783, 108069, '<td valign="top">Excellent photo, and in the words of a meteorologist, or at least a pilot. Great tones. Extremely well done.</td>', 'Excellent photo, and in the words of a meteorologist, or at least a pilot. Great tones. Extremely well done.', '2010-11-25 05:47:07.000000', NULL, 1),
(6232884, 921049, 108069, '<td valign="top">Love the lighting. Great tones. I would have rotated it slightly ccw to get the frame of the farmhouse perfectly vertical, but it''s not a major complaint. Very nice shot.</td>', 'Love the lighting. Great tones. I would have rotated it slightly ccw to get the frame of the farmhouse perfectly vertical, but it''s not a major complaint. Very nice shot.', '2010-11-25 06:41:15.000000', NULL, 1),
(6232950, 921182, 123483, '<td valign="top">Not sure this is about the clouds, but it is a fabulous silhouette.</td>', 'Not sure this is about the clouds, but it is a fabulous silhouette.', '2010-11-25 09:15:59.000000', NULL, 1),
(6233009, 920890, 76335, '<td valign="top">Bit of a cliche, but engaging and nicely executed anyway.</td>', 'Bit of a cliche, but engaging and nicely executed anyway.', '2010-11-25 12:08:59.000000', NULL, 1),
(6233011, 921051, 76335, '<td valign="top">Beautifully composed, exposed. Good use of thirds.</td>', 'Beautifully composed, exposed. Good use of thirds.', '2010-11-25 12:09:31.000000', NULL, 1),
(6233012, 920955, 76335, '<td valign="top">I like the contrast between the warm clouds and cool, even cold, village.</td>', 'I like the contrast between the warm clouds and cool, even cold, village.', '2010-11-25 12:10:13.000000', NULL, 1),
(6233013, 921239, 76335, '<td valign="top">Beautifully composed. The sky feels huge. Clouds strike me as a bit oversharpened.</td>', 'Beautifully composed. The sky feels huge. Clouds strike me as a bit oversharpened.', '2010-11-25 12:10:53.000000', NULL, 1),
(6233014, 921289, 76335, '<td valign="top">I do like the layers here, and I''m not even put off by the centering of the moon. There''s a very pleasing harmony to your composition.</td>', 'I do like the layers here, and I''m not even put off by the centering of the moon. There''s a very pleasing harmony to your composition.', '2010-11-25 12:12:19.000000', NULL, 1),
(6233015, 921652, 76335, '<td valign="top">Great colors in the clouds. The weather vane is nicely placed against the orange contours of the clouds.</td>', 'Great colors in the clouds. The weather vane is nicely placed against the orange contours of the clouds.', '2010-11-25 12:13:26.000000', NULL, 1),
(6233016, 920904, 76335, '<td valign="top">The colors are garish and the sky has an unnatural muddy texture.</td>', 'The colors are garish and the sky has an unnatural muddy texture.', '2010-11-25 12:13:56.000000', NULL, 1),
(6233133, 921302, 116631, '<td valign="top">I like this, except the colours are a bit too artificial for my taste.</td>', 'I like this, except the colours are a bit too artificial for my taste.', '2010-11-25 16:50:19.000000', NULL, 1),
(6233136, 921241, 116631, '<td valign="top">I like the silhouettes of the flying birds. I wish the birds in the foreground were more distinct though.</td>', 'I like the silhouettes of the flying birds. I wish the birds in the foreground were more distinct though.', '2010-11-25 16:52:10.000000', NULL, 1),
(6233139, 921072, 116631, '<td valign="top">I like the colours in this.</td>', 'I like the colours in this.', '2010-11-25 16:54:01.000000', NULL, 1),
(6233140, 920966, 116631, '<td valign="top">The chair takes this from an ordinary shot to something special IMHO</td>', 'The chair takes this from an ordinary shot to something special IMHO', '2010-11-25 16:54:03.000000', NULL, 1),
(6233158, 920993, 24511, '<td valign="top">I was told once that placing your subject smack in the middle made it look like a target and that the space nearby would get more attention from the viewer.  I did see the cloudy haze and the branches more interesting than the moon.  I was left with the sense of wanting more color.  Maybe due to the great amount of darkness being used to frame the center light.  Good luck.</td>', 'I was told once that placing your subject smack in the middle made it look like a target and that the space nearby would get more attention from the viewer.  I did see the cloudy haze and the branches more interesting than the moon.  I was left with the sense of wanting more color.  Maybe due to the great amount of darkness being used to frame the center light.  Good luck.', '2010-11-25 17:41:24.000000', NULL, 1),
(6233161, 921632, 24511, '<td valign="top">Loved the size.  Distracted by the small amount of whiteness at the far left edge of frame and posts in lower center and near tree in forground also took away my attention from the lovely tree and clouds.  Enjoyed the space taken by ground and blue sky like a curtain embracing the main events.  Liked your photo a lot.  Thanks.</td>', 'Loved the size.  Distracted by the small amount of whiteness at the far left edge of frame and posts in lower center and near tree in forground also took away my attention from the lovely tree and clouds.  Enjoyed the space taken by ground and blue sky like a curtain embracing the main events.  Liked your photo a lot.  Thanks.', '2010-11-25 17:45:53.000000', NULL, 1),
(6233163, 921541, 24511, '<td valign="top">Bold statement photo had my head move back slightly.  I found the top clouds too blotchy and would have raised your score even more had you cropped the photo in half and kept the bottom half.  Loved the interesting grasses in the forground.  Thanks.</td>', 'Bold statement photo had my head move back slightly.  I found the top clouds too blotchy and would have raised your score even more had you cropped the photo in half and kept the bottom half.  Loved the interesting grasses in the forground.  Thanks.', '2010-11-25 17:49:39.000000', NULL, 1),
(6233164, 921465, 24511, '<td valign="top">Very soft milky feeling after seeing a recent harsh photo.  I did not like the small specks doting the water surface but loved the posts and reflections.</td>', 'Very soft milky feeling after seeing a recent harsh photo.  I did not like the small specks doting the water surface but loved the posts and reflections.', '2010-11-25 17:52:01.000000', NULL, 1),
(6233165, 921432, 24511, '<td valign="top">After reading the title I quickly returned to the photo and bam saw a white face centre left with nose and mouth profiled.  This made your otherwise ordinary photo bump up a notch in my scoring.  Cool.</td>', 'After reading the title I quickly returned to the photo and bam saw a white face centre left with nose and mouth profiled.  This made your otherwise ordinary photo bump up a notch in my scoring.  Cool.', '2010-11-25 17:54:46.000000', NULL, 1),
(6233167, 921508, 24511, '<td valign="top">Top photo so far at 7.  I''m amazed at the oval landscape on the far horizon.  Clouds are fantastic.  Great color and spaces between ground,water,ground and sky gives great depth.  Good luck</td>', 'Top photo so far at 7.  I''m amazed at the oval landscape on the far horizon.  Clouds are fantastic.  Great color and spaces between ground,water,ground and sky gives great depth.  Good luck', '2010-11-25 17:59:12.000000', NULL, 1),
(6233168, 921260, 24511, '<td valign="top">I liked that the person''s size makes the clouds immense</td>', 'I liked that the person''s size makes the clouds immense', '2010-11-25 18:00:28.000000', NULL, 1),
(6233170, 921538, 24511, '<td valign="top">My first B/W this challenge.  I find the lines more defined.  Loved the sky.  Wanted something more interesting on the water.  Top score for great lighting in the sky on left clouds my favorite.</td>', 'My first B/W this challenge.  I find the lines more defined.  Loved the sky.  Wanted something more interesting on the water.  Top score for great lighting in the sky on left clouds my favorite.', '2010-11-25 18:02:55.000000', NULL, 1),
(6233172, 921049, 24511, '<td valign="top">Sooo busy yet wonderful.  I like how the shapes of the clouds play with the shapes of the treetops. First 10 this challenge and adding to favorites.  I was surprised I liked it so much not only because it was so busy but it seem to jump at me as very mono tone neither pure whites or deep darks well represented.</td>', 'Sooo busy yet wonderful.  I like how the shapes of the clouds play with the shapes of the treetops. First 10 this challenge and adding to favorites.  I was surprised I liked it so much not only because it was so busy but it seem to jump at me as very mono tone neither pure whites or deep darks well represented.', '2010-11-25 18:07:09.000000', NULL, 1),
(6233174, 921148, 24511, '<td valign="top">Smoke and cloud good combination for me a high score.</td>', 'Smoke and cloud good combination for me a high score.', '2010-11-25 18:09:15.000000', NULL, 1),
(6233176, 921051, 24511, '<td valign="top">High beems in the sky and low beems on the ground made me smile and really enjoy this photo.  Loved it 8</td>', 'High beems in the sky and low beems on the ground made me smile and really enjoy this photo.  Loved it 8', '2010-11-25 18:12:01.000000', NULL, 1),
(6233177, 921526, 24511, '<td valign="top">Scoring 9 for such a superb photo.  But what is a cloud anyways?  Just a lot of gas and air stuff.  Your really getting a bargain in points for capturing,...well like I said...nothing.</td>', 'Scoring 9 for such a superb photo.  But what is a cloud anyways?  Just a lot of gas and air stuff.  Your really getting a bargain in points for capturing,...well like I said...nothing.', '2010-11-25 18:15:22.000000', NULL, 1),
(6233180, 921309, 24511, '<td valign="top">Favorite branch scene.  I believe they stole the show from the clouds and even the moon a little.  Good luck.  Loved the shot.</td>', 'Favorite branch scene.  I believe they stole the show from the clouds and even the moon a little.  Good luck.  Loved the shot.', '2010-11-25 18:17:26.000000', NULL, 1),
(6233183, 921119, 24511, '<td valign="top">Crisp rocks and water my favorite part of the photo.  Clouds an after thought needed more performance to outshine forground.  Really loved that forground.  Good luck.</td>', 'Crisp rocks and water my favorite part of the photo.  Clouds an after thought needed more performance to outshine forground.  Really loved that forground.  Good luck.', '2010-11-25 18:19:15.000000', NULL, 1),
(6233185, 921638, 24511, '<td valign="top">Loved the trees but more importantly the sky could over challenge them with interesting shapes, color and movement.  Liked the framing widescreen gave me a sense of swoosh. Scored 0.  No no I mean a 9.  Thanks.</td>', 'Loved the trees but more importantly the sky could over challenge them with interesting shapes, color and movement.  Liked the framing widescreen gave me a sense of swoosh. Scored 0.  No no I mean a 9.  Thanks.', '2010-11-25 18:23:33.000000', NULL, 1),
(6233187, 921262, 24511, '<td valign="top">This photo made me believe I was in a cloud.  Had me enter and participate in the photo.  I even sqwinted trying to get a better view.  Good luck.</td>', 'This photo made me believe I was in a cloud.  Had me enter and participate in the photo.  I even sqwinted trying to get a better view.  Good luck.', '2010-11-25 18:27:29.000000', NULL, 1),
(6233189, 921239, 24511, '<td valign="top">Didn''t like the ground ending in the bottom corner of the frame.  Didn''t care.  Best entry in my opinion and ten time ten.  Good luck.</td>', 'Didn''t like the ground ending in the bottom corner of the frame.  Didn''t care.  Best entry in my opinion and ten time ten.  Good luck.', '2010-11-25 18:32:03.000000', NULL, 1),
(6233192, 921595, 24511, '<td valign="top">Smoking gun, all 9 clouds bonanza winner photo.  Congratulations.</td>', 'Smoking gun, all 9 clouds bonanza winner photo.  Congratulations.', '2010-11-25 18:34:53.000000', NULL, 1),
(6233193, 921044, 24511, '<td valign="top">I''m no scientist so this photo looked more like fish smimming just under the surface of the water.  Good luck.</td>', 'I''m no scientist so this photo looked more like fish smimming just under the surface of the water.  Good luck.', '2010-11-25 18:36:54.000000', NULL, 1),
(6233194, 921590, 24511, '<td valign="top">I knew after seeing the photo that your title would include something reflecting the great attention grabbing shapes.  Had me comparing the three and spending even more time looking at your photo.  Loves it.</td>', 'I knew after seeing the photo that your title would include something reflecting the great attention grabbing shapes.  Had me comparing the three and spending even more time looking at your photo.  Loves it.', '2010-11-25 18:39:41.000000', NULL, 1),
(6233195, 921572, 24511, '<td valign="top">Great looking photo and scoring high but had trouble with the size on computer screen.</td>', 'Great looking photo and scoring high but had trouble with the size on computer screen.', '2010-11-25 18:41:48.000000', NULL, 1),
(6233196, 921245, 24511, '<td valign="top">For such a small amount of space in the whole surface of your photo, the clouds have tremendous presence.  Appreciated 8</td>', 'For such a small amount of space in the whole surface of your photo, the clouds have tremendous presence.  Appreciated 8', '2010-11-25 18:45:14.000000', NULL, 1),
(6233200, 920926, 24511, '<td valign="top">Too much light to see the clouds.  Good luck.</td>', 'Too much light to see the clouds.  Good luck.', '2010-11-25 18:47:12.000000', NULL, 1),
(6233202, 921591, 24511, '<td valign="top">I really loved the photo but got lost in the title.  I''m a visual and reading the whole title from start to finish moved me away from the beauty of the image.  Good luck</td>', 'I really loved the photo but got lost in the title.  I''m a visual and reading the whole title from start to finish moved me away from the beauty of the image.  Good luck', '2010-11-25 18:48:53.000000', NULL, 1),
(6233204, 920931, 24511, '<td valign="top">Shazam I''m a fan of this story type of image.  Very special to me and I wasn''t even there.  Favorite for me for sure.  Loved the mood and shadings.  Thanks 9</td>', 'Shazam I''m a fan of this story type of image.  Very special to me and I wasn''t even there.  Favorite for me for sure.  Loved the mood and shadings.  Thanks 9', '2010-11-25 18:51:37.000000', NULL, 1),
(6233205, 920826, 24511, '<td valign="top">Red sky at night, sailors delight.  Loved the horizontal smooth lines in the clouds held by sharp edge branches.  Found the photo quite dark.  Thanks 7</td>', 'Red sky at night, sailors delight.  Loved the horizontal smooth lines in the clouds held by sharp edge branches.  Found the photo quite dark.  Thanks 7', '2010-11-25 18:57:40.000000', NULL, 1),
(6233210, 920997, 81362, '<td valign="top">Back to bump up a point after finally seeing the face in the thumbnail. Full size, the drops capture the most attention, but the overall effect is interesting.</td>', 'Back to bump up a point after finally seeing the face in the thumbnail. Full size, the drops capture the most attention, but the overall effect is interesting.', '2010-11-25 19:26:43.000000', NULL, 1),
(6233213, 921302, 116649, '<td valign="top">I love the color selection, makes me feel right at home!</td>', 'I love the color selection, makes me feel right at home!', '2010-11-25 19:36:01.000000', NULL, 1),
(6233217, 921560, 116649, '<td valign="top">Great capture, patience pays!</td>', 'Great capture, patience pays!', '2010-11-25 19:42:01.000000', NULL, 1),
(6233220, 921115, 116649, '<td valign="top">Love the Colors</td>', 'Love the Colors', '2010-11-25 20:02:44.000000', NULL, 1),
(6233294, 921665, 112739, '<td valign="top">Very spooky, very nice. Timing is everything.</td>', 'Very spooky, very nice. Timing is everything.', '2010-11-25 22:58:14.000000', NULL, 1),
(6233363, 921603, 86218, '<td valign="top">Lovely mood created here with the clouds, shadows and light</td>', 'Lovely mood created here with the clouds, shadows and light', '2010-11-26 00:31:08.000000', NULL, 1),
(6233365, 921198, 86218, '<td valign="top">I just love this scene. Must be a reason why tree on left was cropped but its a nice tree to include in frame. 8</td>', 'I just love this scene. Must be a reason why tree on left was cropped but its a nice tree to include in frame. 8', '2010-11-26 00:33:08.000000', NULL, 1),
(6233380, 921526, 86218, '<td valign="top">Great shot.</td>', 'Great shot.', '2010-11-26 00:44:32.000000', NULL, 1),
(6233383, 921560, 86218, '<td valign="top">Some great clouds formed here and like that you waited for the light to seperate and contrast them.</td>', 'Some great clouds formed here and like that you waited for the light to seperate and contrast them.', '2010-11-26 00:47:21.000000', NULL, 1),
(6233387, 921632, 86218, '<td valign="top">This scene could do without the pbject in the fore popping up and ruining it. With a little effort maybe move closer and have the tree form a bigger part of this photo..thats if you were not prevented by a fence/private property</td>', 'This scene could do without the pbject in the fore popping up and ruining it. With a little effort maybe move closer and have the tree form a bigger part of this photo..thats if you were not prevented by a fence/private property', '2010-11-26 00:50:08.000000', NULL, 1),
(6233393, 921571, 86218, '<td valign="top">Familiar scene and good clouds forming a line making a general scene more interesting. Colours in the fore looks odd. Maybe to much contrast and sats here?</td>', 'Familiar scene and good clouds forming a line making a general scene more interesting. Colours in the fore looks odd. Maybe to much contrast and sats here?', '2010-11-26 00:53:41.000000', NULL, 1),
(6233535, 921266, 119040, '<td valign="top">very intense</td>', 'very intense', '2010-11-26 01:42:50.000000', NULL, 1),
(6233543, 921538, 119040, '<td valign="top">i think i would have liked it more if it was in color, but still very calming</td>', 'i think i would have liked it more if it was in color, but still very calming', '2010-11-26 01:44:04.000000', NULL, 1),
(6233552, 921230, 119040, '<td valign="top">the title is what makes this pic</td>', 'the title is what makes this pic', '2010-11-26 01:46:00.000000', NULL, 1),
(6233559, 921051, 119040, '<td valign="top">if the industrial objects weren''t in the shot it would have been so much better</td>', 'if the industrial objects weren''t in the shot it would have been so much better', '2010-11-26 01:47:29.000000', NULL, 1),
(6233764, 921575, 124017, '<td valign="top">I don''t think that the clouds are the clear feature of this photo.</td>', 'I don''t think that the clouds are the clear feature of this photo.', '2010-11-26 05:56:45.000000', NULL, 1),
(6233834, 920966, 61725, '<td valign="top">Absolutely fantastic!!! A 10!!</td>', 'Absolutely fantastic!!! A 10!!', '2010-11-26 08:28:15.000000', NULL, 1),
(6234129, 921230, 26464, '<td valign="top">great concept</td>', 'great concept', '2010-11-26 12:25:31.000000', NULL, 1),
(6234130, 921266, 26464, '<td valign="top">wow... impressive clouds. like rolling smoke.</td>', 'wow... impressive clouds. like rolling smoke.', '2010-11-26 12:26:02.000000', NULL, 1),
(6234131, 921605, 26464, '<td valign="top">love the mood here.</td>', 'love the mood here.', '2010-11-26 12:26:15.000000', NULL, 1),
(6234135, 921524, 26464, '<td valign="top">a very moody photo, i like it</td>', 'a very moody photo, i like it', '2010-11-26 12:27:23.000000', NULL, 1),
(6234138, 921262, 26464, '<td valign="top">wow, almost looks surreal.</td>', 'wow, almost looks surreal.', '2010-11-26 12:27:58.000000', NULL, 1),
(6234142, 921534, 26464, '<td valign="top">love the concept, good contrast. to me would have been even better with the foreground cropped out.</td>', 'love the concept, good contrast. to me would have been even better with the foreground cropped out.', '2010-11-26 12:30:00.000000', NULL, 1),
(6234143, 921646, 26464, '<td valign="top">amazing use of contrast.</td>', 'amazing use of contrast.', '2010-11-26 12:30:25.000000', NULL, 1),
(6234212, 921571, 108069, '<td valign="top">Outstanding viewpoint. Not voting, just commenting. I would have hacked a bit of that sky off, but it is a lovely blue and that''s tough to do. Is this SA? Never been, but this is how I''d imagine it.</td>', 'Outstanding viewpoint. Not voting, just commenting. I would have hacked a bit of that sky off, but it is a lovely blue and that''s tough to do. Is this SA? Never been, but this is how I''d imagine it.', '2010-11-26 13:01:43.000000', NULL, 1),
(6234290, 921198, 123348, '<td valign="top">Like a beautiful painting, definitely a ten!</td>', 'Like a beautiful painting, definitely a ten!', '2010-11-26 14:10:59.000000', NULL, 1),
(6234291, 920890, 123348, '<td valign="top">Great colors and reflection, wonderful image!</td>', 'Great colors and reflection, wonderful image!', '2010-11-26 14:11:36.000000', NULL, 1),
