(6235904, 921400, 6565, '<td valign="top">Awesome colors, really sets a mood.</td>', 'Awesome colors, really sets a mood.', '2010-11-28 10:37:59.000000', NULL, 1),
(6235905, 921381, 6565, '<td valign="top">Love the drama in this image -- it''s just lovely! I don''t think I would have been able to guess that it was for a clouds challenge, but that doesn''t detract from its general interest.</td>', 'Love the drama in this image -- it''s just lovely! I don''t think I would have been able to guess that it was for a clouds challenge, but that doesn''t detract from its general interest.', '2010-11-28 10:38:07.000000', NULL, 1),
