(6235908, 920966, 6565, '<td valign="top">I actually think this one would be stronger without the chair.</td>', 'I actually think this one would be stronger without the chair.', '2010-11-28 10:44:23.000000', NULL, 1),
(6235942, 921260, 114225, '<td valign="top">Great scene. I like the mixture of colors and the impeding storm.</td>', 'Great scene. I like the mixture of colors and the impeding storm.', '2010-11-28 11:12:02.000000', NULL, 1),
(6235945, 921289, 114225, '<td valign="top">Good job with exposure balancing on a scene that seems difficult. It''s too bad there are those lens element reflections near the top of the photograph, those really distract the viewer. I''m wondering if you left a UV filter on your lens, which I found out often causes those types of reflections.</td>', 'Good job with exposure balancing on a scene that seems difficult. It''s too bad there are those lens element reflections near the top of the photograph, those really distract the viewer. I''m wondering if you left a UV filter on your lens, which I found out often causes those types of reflections.', '2010-11-28 11:13:41.000000', NULL, 1),
(6235950, 920829, 114225, '<td valign="top">Nicely composed. Including so much of the sky in this photo really gives a feeling of expansiveness.</td>', 'Nicely composed. Including so much of the sky in this photo really gives a feeling of expansiveness.', '2010-11-28 11:15:16.000000', NULL, 1),
