(6239565, 920853, 11769, '<td valign="top">Love the color.</td>', 'Love the color.', '2010-12-01 00:37:23.000000', NULL, 0),
(6239567, 921008, 99392, '<td valign="top">Great capture and congrats on an awesome finish.  This was one of my favorites of the challenge.</td>', 'Great capture and congrats on an awesome finish.  This was one of my favorites of the challenge.', '2010-12-01 00:37:27.000000', NULL, 0),
(6239568, 920926, 70484, '<td valign="top">I love this capture!!! It was one of my 9''s. Always amazes me that the very artistic score very low, but I see that you got a posthumous red ribbon!!!! That is so much better than a high score! Way to go. Beautiful capture!</td>', 'I love this capture!!! It was one of my 9''s. Always amazes me that the very artistic score very low, but I see that you got a posthumous red ribbon!!!! That is so much better than a high score! Way to go. Beautiful capture!', '2010-12-01 00:37:37.000000', NULL, 0),
(6239577, 921507, 67697, '<td valign="top">I love how you use motion blur to create a natural painterly look.  The dappled birds are my favorite part.</td>', 'I love how you use motion blur to create a natural painterly look.  The dappled birds are my favorite part.', '2010-12-01 00:41:08.000000', NULL, 0),
(6239579, 920634, 66709, '<td valign="top">YOU got rob!</td>', 'YOU got rob!', '2010-12-01 00:42:04.000000', NULL, 0),
