(6239583, 921567, 113591, '<td valign="top">Wonderlik Rian. Dankie vir al die info. Dit gee mens stukrag om meer moeite te doen vir goeie foto''s. Jy''s die weerlig-koning. Die balans en kleurskakerings is vir my die uitstaande kenmerke in die foto . Twee rosette vir Suid-Afrika - mooi so!<br/><br/><i>Message edited by author 2010-12-01 00:45:01.</i></td>', 'Wonderlik Rian. Dankie vir al die info. Dit gee mens stukrag om meer moeite te doen vir goeie foto''s. Jy''s die weerlig-koning. Die balans en kleurskakerings is vir my die uitstaande kenmerke in die foto . Twee rosette vir Suid-Afrika - mooi so!', '2010-12-01 00:43:28.000000', '2010-12-01 00:45:01.000000', 0),
(6239585, 921062, 59267, '<td valign="top">Congratulations on your ribbon! Awesome shot!</td>', 'Congratulations on your ribbon! Awesome shot!', '2010-12-01 00:46:33.000000', NULL, 0),
(6239588, 921239, 59267, '<td valign="top">Excellent shot! congratulations!</td>', 'Excellent shot! congratulations!', '2010-12-01 00:49:05.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6239590, 921347, 113591, '<td valign="top">Very nice shot, Konrad. Two ribbons for RSA - Way to go!.</td>', 'Very nice shot, Konrad. Two ribbons for RSA - Way to go!.', '2010-12-01 00:49:12.000000', NULL, 0),
(6239596, 921008, 59267, '<td valign="top">Great shot! love the view!</td>', 'Great shot! love the view!', '2010-12-01 00:51:54.000000', NULL, 0),
(6239599, 921232, 59267, '<td valign="top">What a view! great shot!</td>', 'What a view! great shot!', '2010-12-01 00:53:52.000000', NULL, 0),
(6239602, 921543, 99392, '<td valign="top">One of my very favorite shots in the challenge.</td>', 'One of my very favorite shots in the challenge.', '2010-12-01 00:55:51.000000', NULL, 0),
(6239603, 921560, 86218, '<td valign="top">Hey Amanda!! Ek het regtig nie geweet die is joune nie. Se vir Bees jou maaitjie het Hoe punte gegee sonder om te weet dit is joune ;) Mal oor die foto. Top 10 en jy verdien dit.</td>', 'Hey Amanda!! Ek het regtig nie geweet die is joune nie. Se vir Bees jou maaitjie het Hoe punte gegee sonder om te weet dit is joune ;) Mal oor die foto. Top 10 en jy verdien dit.', '2010-12-01 00:55:52.000000', NULL, 0),
(6239606, 921062, 113591, '<td valign="top">The blurry clouds do seem to be zipping towards you. Very nice effect. <strike>Carbon</strike>candy-neutral? Depends on whether or not you had a chocolate bar whist peddaling from home to the seaside.</td>', 'The blurry clouds do seem to be zipping towards you. Very nice effect. Carboncandy-neutral? Depends on whether or not you had a chocolate bar whist peddaling from home to the seaside.', '2010-12-01 00:57:07.000000', NULL, 0),
(6239612, 921571, 86218, '<td valign="top">What in the world... Paul??? Are you visiting SA? Welcome here and enjoy. I was totally surpised to see this as your pic. I NEVER would have figured it yours since you are from UK and this is not your style as you also note.</td>', 'What in the world... Paul??? Are you visiting SA? Welcome here and enjoy. I was totally surpised to see this as your pic. I NEVER would have figured it yours since you are from UK and this is not your style as you also note.', '2010-12-01 01:03:36.000000', NULL, 0),
(6239614, 921567, 108580, '<td valign="top">Uitstekende resultaat Rian. Soms is dit sulke strond wat jou kwaad maak, waar jy die beste foto''s kry. Mooi om te sien ''ons'' fotograwe is in eerste en tweede plek.<br/>Well done!</td>', 'Uitstekende resultaat Rian. Soms is dit sulke strond wat jou kwaad maak, waar jy die beste foto''s kry. Mooi om te sien ''ons'' fotograwe is in eerste en tweede plek.Well done!', '2010-12-01 01:04:38.000000', NULL, 0),
(6239615, 921560, 113591, '<td valign="top">Baie mooi en dramaties. Hoop nie die wolk het julle met klippe gegooi nie, ek hoor daar was baie hael in jou omgewing die afgelope maand.</td>', 'Baie mooi en dramaties. Hoop nie die wolk het julle met klippe gegooi nie, ek hoor daar was baie hael in jou omgewing die afgelope maand.', '2010-12-01 01:05:28.000000', NULL, 0),
(6239617, 920853, 113591, '<td valign="top">This is beautiful - has a 3-D feel to it.</td>', 'This is beautiful - has a 3-D feel to it.', '2010-12-01 01:06:28.000000', NULL, 0),
(6239620, 921347, 108580, '<td valign="top">Al weer julle Kaapenaars met julle mooi strande. Ek was daar laas week maar kon ongelukkig nie met jou of Philip praat nie want my tyd was propvol met familie en hulle wense. Ek was rerig kwaad to ek by Kogal Baai en Gordon''s Baai moes verby ry...next time!<br/>Superb work Konrad.</td>', 'Al weer julle Kaapenaars met julle mooi strande. Ek was daar laas week maar kon ongelukkig nie met jou of Philip praat nie want my tyd was propvol met familie en hulle wense. Ek was rerig kwaad to ek by Kogal Baai en Gordon''s Baai moes verby ry...next time!Superb work Konrad.', '2010-12-01 01:07:33.000000', NULL, 0),
(6239626, 921062, 108580, '<td valign="top">Lovely work mate. Not too flashy and yet calming and dramatic at the same time if that''s possible. Well done on your ribbon...nature prevails, 1, 2 and 3!</td>', 'Lovely work mate. Not too flashy and yet calming and dramatic at the same time if that''s possible. Well done on your ribbon...nature prevails, 1, 2 and 3!', '2010-12-01 01:08:54.000000', NULL, 0),
(6239627, 921489, 113591, '<td valign="top">Well-spotted. I liked this one most of all.</td>', 'Well-spotted. I liked this one most of all.', '2010-12-01 01:09:09.000000', NULL, 0),
(6239630, 921239, 108580, '<td valign="top">Wow, so much impact and yet so simple. WD on HM</td>', 'Wow, so much impact and yet so simple. WD on HM', '2010-12-01 01:11:16.000000', NULL, 0),
(6239631, 921567, 93421, '<td valign="top">Congrats on the Blue Rian - a stunning capture!  Two South African manne on the front page.  Mooi so!</td>', 'Congrats on the Blue Rian - a stunning capture!  Two South African manne on the front page.  Mooi so!', '2010-12-01 01:11:34.000000', NULL, 0),
(6239633, 921198, 108580, '<td valign="top">Beautiful, soft, colourful but not comic-like. WD on HM</td>', 'Beautiful, soft, colourful but not comic-like. WD on HM', '2010-12-01 01:11:53.000000', NULL, 0),
