(6239662, 921347, 86218, '<td valign="top">Baie Geluk Konrad. Oppad Kaap toe in Desember en wil graag die plek sien wat julle (Philip en jy) so mooi laat lyk. Ek sal dit sonder my kamera doen. Ek wil nie eers probeer om fotos daar te neem nie en net die omgewing geniet.</td>', 'Baie Geluk Konrad. Oppad Kaap toe in Desember en wil graag die plek sien wat julle (Philip en jy) so mooi laat lyk. Ek sal dit sonder my kamera doen. Ek wil nie eers probeer om fotos daar te neem nie en net die omgewing geniet.', '2010-12-01 01:26:26.000000', NULL, 0),
(6239667, 921062, 88850, '<td valign="top">Congratulations Ben!  What an outstanding shot!!!</td>', 'Congratulations Ben!  What an outstanding shot!!!', '2010-12-01 01:29:17.000000', NULL, 0),
(6239669, 921524, 16241, '<td valign="top">you beat me bitch, lol@photographer''s comment.</td>', 'you beat me bitch, lol@photographer''s comment.', '2010-12-01 01:29:48.000000', NULL, 0),
