(6239709, 920926, 30982, '<td valign="top">Slight differential there between your overall score and that from your commenters.  Possibly a record.  :-)  Nice to see you playing here again!</td>', 'Slight differential there between your overall score and that from your commenters.  Possibly a record.  :-)  Nice to see you playing here again!', '2010-12-01 02:20:09.000000', NULL, 0),
(6239716, 921507, 62357, '<td valign="top">Didn''t get chance to vote on this challenge.  This is the first time I''ve seen this image and I have to say, I love it.</td>', 'Didn''t get chance to vote on this challenge.  This is the first time I''ve seen this image and I have to say, I love it.', '2010-12-01 02:43:38.000000', NULL, 0),
